"  const [customChargeValue, setCustomChargeValue] = useState('');

  const mergeCartItems = (existingItems, newItems) => {
    if (!existingItems || existingItems.length === 0) return [...newItems];
    const merged = [...existingItems];
    newItems.forEach(newItem => {
      const existingIndex = merged.findIndex(item => {
        const idMatch = item.id === newItem.id;
        const priceMatch = parseFloat(item.price || 0) === parseFloat(newItem.price || 0);
        const labelMatch = item.priceLabel === newItem.priceLabel;
        const compMatch = !!item.isComplementary === !!newItem.isComplementary;
        const cancelMatch = !!item.isCancelled === !!newItem.isCancelled;

        const itemMods = item.modifiers || [];
        const newMods = newItem.modifiers || [];
        const modsMatch = itemMods.length === newMods.length && 
          itemMods.every(m => newMods.some(nm => nm.name === m.name && parseFloat(nm.price || 0) === parseFloat(m.price || 0)));

        return idMatch && priceMatch && labelMatch && compMatch && cancelMatch && modsMatch;
      });

      if (existingIndex > -1) {
        merged[existingIndex] = {
          ...merged[existingIndex],
          quantity: (merged[existingIndex].quantity || 0) + (newItem.quantity || 0)
        };
      } else {
        merged.push({ ...newItem });
      }
    });
    return merged;
  };"
